sp_widget.client_script:
api.controller = function($scope, $http) {
    // Initialisieren der Variablen
    $scope.selectedRitm = null; // Für die Auswahl des Requested Items
    $scope.deliveryDates = [];  // Array zur Speicherung mehrerer Liefertermine
    $scope.data.successMessage = ''; // Für Erfolgsmeldungen
		debugger;
		$scope.data.requestedItems = function() {
        alert($scope.requestedItems());
    };
    // Überprüfen, ob die Requested Items korrekt geladen wurden
    console.log("Loaded Requested Items:", $scope.data.requestedItems);

    // Funktion, um Liefertermine hinzuzufügen
    $scope.addDate = function() {
        $scope.deliveryDates.push({ date: '' });
    };

    // Funktion, um einen Liefertermin zu entfernen
    $scope.removeDate = function(index) {
        if (index >= 0 && index < $scope.deliveryDates.length) {
            $scope.deliveryDates.splice(index, 1);
        }
    };

    // Überwachung der Dropdown-Auswahl (optional)
    $scope.$watch('selectedRitm', function(newValue) {
        if (newValue) {
            console.log("Ausgewähltes Requested Item:", newValue);
        }
    });

    // Funktion zum Speichern der Liefertermine
    $scope.saveDeliveryDates = function() {
        if (!$scope.selectedRitm || $scope.deliveryDates.length === 0) {
            alert("Bitte ein Requested Item auswählen und mindestens einen Liefertermin hinzufügen.");
            return;
        }

        // Payload für das Server Script vorbereiten
        const payload = {
            ritmSysId: $scope.selectedRitm.sys_id,
            dates: $scope.deliveryDates.map(date => date.date)
        };
				debugger;
        // HTTP POST-Anfrage an das Server Script senden
        $http.post('/api/now/ui/widget/' + $scope.data.widgetInstance, payload).then(function(response) {
            if (response.data.result.success) {
                $scope.data.successMessage = "Liefertermine wurden erfolgreich gespeichert!";
                $scope.deliveryDates = [];
                $scope.selectedRitm = null;
            } else {
                alert("Fehler beim Speichern der Liefertermine");
            }
        }, function(error) {
            console.error("Fehler bei der HTTP-Anfrage:", error);
            alert("Fehler beim Speichern der Liefertermine");
        });
    };
};

sp_widget.css:
.widget-title {
    color: #0072C6;
    margin-bottom: 20px;
}
.delivery-section {
    margin-top: 20px;
}
.form-control {
    margin-bottom: 10px;
    width: 100%;
}
.btn {
    margin-top: 10px;
    margin-right: 10px;
}
.alert {
    margin-top: 20px;
}

sp_widget.script:
(function() {
	 requestedItems = function() {
			var requestedItems = [];
      var gr = new GlideRecord('sc_req_item');
      gr.addQuery('state', '=', 1);
      gr.orderByDesc('sys_created_on');
      gr.query();

       while (gr.next()) {
					requestedItems.push({
						sys_id: gr.getValue('sys_id'),
						number: gr.getValue('number'),
						short_description: gr.getValue('short_description')
					});
        }
				return requestedItems;
    };

})();
